    // for both the game-state and the level flag (0x004C885D reads the inline's result word, 0x004C8899 the local).
    bool persistent = IsGameStatePersisted();
    IsLevelPersistent();
    context.Transfer(persistent);
    context.Transfer(persistent);
}

